def backfill_notices(apps, schema_editor):
    """Each open notice from before D-106 gets its move-out day and a history row (given by the tenant, the
    usual case, and in person, since the old form did not ask)."""
    Lease = apps.get_model("leases", "Lease")
    LeaseNotice = apps.get_model("leases", "LeaseNotice")
    for lease in Lease._base_manager.filter(notice_given_on__isnull=False).iterator():
        lease.move_out_on = lease.notice_given_on + datetime.timedelta(days=lease.notice_days)
        lease.save(update_fields=["move_out_on"])
        LeaseNotice.objects.create(organization_id=lease.organization_id, lease=lease, given_by="TENANT",
                                   given_on=lease.notice_given_on, move_out_on=lease.move_out_on, via="IN_PERSON")


